<?php require 'config/database.php'; session_start(); $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??''); $email=trim($_POST['email']??''); $password=$_POST['password']??''; if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<6){$msg='Please enter valid information. Password must be at least 6 characters.';}else{$check=$conn->prepare("SELECT id FROM users WHERE email=?");$check->bind_param("s",$email);$check->execute();$check->store_result();if($check->num_rows>0){$msg='Email already registered.';}else{$hash=password_hash($password,PASSWORD_DEFAULT);$stmt=$conn->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'user')");$stmt->bind_param("sss",$name,$email,$hash);if($stmt->execute()){header('Location: login.php?registered=1');exit;}else{$msg='Registration failed.';}}}} $pageTitle='Register'; include 'header.php'; ?><h2>Register</h2><?php if($msg):?><div class="alert error"><?=htmlspecialchars($msg)?></div><?php endif;?><form method="post"><label>Name</label><input type="text" name="name" required><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" minlength="6" required><button class="btn" type="submit">Create Account</button></form><?php include 'footer.php'; ?>